export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
  const [posts, categories] = await Promise.all([
    client.fetch<{ slug: string; _updatedAt: string }[]>(allPostSlugsQuery),
    client.fetch<{ slug: string }[]>(allCategorySlugsQuery),
  ]);

  return [
    { url: siteUrl, changeFrequency: "daily", priority: 1 },
    ...STATIC_ROUTES.map((path) => ({
      url: `${siteUrl}${path}`,
      changeFrequency: "monthly" as const,
      priority: 0.7,
    })),
    ...posts.map((post) => ({
      url: `${siteUrl}/blog/${post.slug}`,
      lastModified: post._updatedAt,
      changeFrequency: "monthly" as const,
      priority: 0.6,
    })),
    ...categories.map((category) => ({
      url: `${siteUrl}/blog/category/${category.slug}`,
      changeFrequency: "weekly" as const,
      priority: 0.5,
    })),
    ...CITIES.map((city) => ({
      url: `${siteUrl}/brewsoul/cities/${city.slug}`,
      changeFrequency: "monthly" as const,
      priority: 0.5,
    })),
    ...BREWSOUL_COFFEES.map((coffee) => ({
      url: `${siteUrl}/brewsoul/coffee/${coffee.id}`,
      changeFrequency: "monthly" as const,
      priority: 0.5,
    })),
    ...CHARITIES.map((charity) => ({
      url: `${siteUrl}/charity-scorecard/${charity.slug}`,
      changeFrequency: "monthly" as const,
      priority: 0.5,
    })),
  ];
}
